  function drawLoss(values){const canvas=document.querySelector('#cluster-loss-chart'),{ctx,width,height}=prepareCanvas(canvas),pad=32,theme=canvasTheme(ctx);ctx.strokeStyle=theme.line;ctx.beginPath();ctx.moveTo(pad,12);ctx.lineTo(pad,height-pad);ctx.lineTo(width-10,height-pad);ctx.stroke();if(!values.length)return;const max=Math.max(...values,1),min=Math.min(...values),span=max-min||1;drawLine(ctx,values.map((value,index)=>[pad+(width-pad-14)*(values.length===1?0:index/(values.length-1)),14+(height-pad-18)*(max-value)/span]),'#207b61',2);ctx.fillStyle=theme.muted;ctx.font='10px Segoe UI';ctx.fillText(`起始 ${formatValue(values[0],2)}`,pad,11);ctx.fillText(`最终 ${formatValue(values.at(-1),2)}`,Math.max(pad,width-105),height-8)}
